#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

TOTAL_STAGES=8
ENV_FILE=".dev.vars"              # the same values go-live.sh copied to the old kereta worker
CF_ENV_FILE=".cloudflare.env"     # Cloudflare API token on headless servers (from go-live.sh)
cd "$(dirname "$0")/.."

# Over SSH there's no browser here: print links to open on your own computer instead.
if [[ -n "${SSH_CONNECTION:-}${SSH_TTY:-}" ]] ||
   [[ "$(uname)" == Linux && -z "${DISPLAY:-}${WAYLAND_DISPLAY:-}" ]] && ! command -v wslview >/dev/null 2>&1; then
  open_url() { printf '  %s↗ open on your computer:%s %s\n' "$GREEN" "$RESET" "$1"; }
fi
if [[ -f "$CF_ENV_FILE" ]]; then set -a; . "./$CF_ENV_FILE"; set +a; fi

SECRETS=(GOOGLE_CLIENT_ID GOOGLE_CLIENT_SECRET SESSION_SECRET OPENROUTER_API_KEY CONTACT_EMAIL)
APP_URL=""
OLD_URL=""

banner "Move the live app from Kereta to Lejar"

# ── 1 ────────────────────────────────────────────────────────────────────
stage "Check: was Kereta ever live?"
if [[ -z "$(_existing GOOGLE_CLIENT_ID || true)" ]]; then
  warn "No GOOGLE_CLIENT_ID in $ENV_FILE, so go-live.sh probably never ran."
  say "If the app was never deployed, there is nothing to move: run ${BOLD}./scripts/go-live.sh${RESET} instead."
  if ! confirm "Was Kereta live anyway (and you have the secret values to hand)?"; then
    say "Run ./scripts/go-live.sh. It now sets everything up under the Lejar name."; exit 0
  fi
else
  say "${GREEN}✓${RESET} Found the production values go-live.sh saved in $ENV_FILE."
fi
if [[ "$(git rev-parse --abbrev-ref HEAD)" != "master" ]]; then
  warn "You're on branch '$(git rev-parse --abbrev-ref HEAD)'. Merge the rename into master first,"
  note "  so the CI deploy on master and this deploy agree. Deploying from here also works."
  confirm "Deploy from this branch anyway?" || exit 0
fi
pause

# ── 2 ────────────────────────────────────────────────────────────────────
stage "Cloudflare: signed in?"
if npx wrangler whoami 2>/dev/null | grep -qE "You are logged in|associated with|API Token"; then
  say "${GREEN}✓${RESET} Wrangler can reach your Cloudflare account."
else
  warn "Wrangler isn't signed in. Run ./scripts/go-live.sh stage 1, or 'npx wrangler login', then re-run this wizard."
  exit 1
fi
pause

# ── 3 ────────────────────────────────────────────────────────────────────
stage "Cloudflare: secrets for the new 'lejar' worker"
say "A renamed worker is a new worker on Cloudflare, so the secrets have to be set again."
say "SESSION_SECRET stays the same value; the new address signs everyone out anyway."
for name in "${SECRETS[@]}"; do
  if [[ -z "$(_existing "$name" || true)" ]]; then
    if [[ "$name" == CONTACT_EMAIL ]]; then ask "$name" "Value for $name:"; else ask_secret "$name" "Value for $name:"; fi
    write_env "$name" "${!name}"
  else
    printf -v "$name" '%s' "$(_existing "$name")"
  fi
done
if confirm "Set ${SECRETS[*]} on the 'lejar' worker?"; then
  for name in "${SECRETS[@]}"; do
    if printf '%s' "${!name}" | npx wrangler secret put "$name" --name lejar >/dev/null 2>&1; then
      printf '  %s✓ set%s %s\n' "$GREEN" "$RESET" "$name"
    else
      SKIPPED+=("Cloudflare secret $name (npx wrangler secret put $name --name lejar)")
      warn "couldn't set $name; run: npx wrangler secret put $name --name lejar"
    fi
  done
else
  SKIPPED+=("set the five secrets on the lejar worker")
fi
pause

# ── 4 ────────────────────────────────────────────────────────────────────
stage "Deploy Lejar and check it answers"
APP_URL=$(npx wrangler deploy 2>&1 | tee /dev/stderr | grep -oE 'https://lejar\.[a-z0-9-]+\.workers\.dev' | head -1 || true)
if [[ -z "$APP_URL" ]]; then
  warn "Couldn't spot the new address in the deploy output."
  ask APP_URL "Paste it (https://lejar.<subdomain>.workers.dev):"
fi
APP_URL="${APP_URL%/}"
OLD_URL="${APP_URL/:\/\/lejar./://kereta.}"   # same workers.dev subdomain, old worker name
HEALTH=$(curl -fsS "$APP_URL/healthz" 2>/dev/null || true)
if [[ "$HEALTH" == "ok" ]]; then say "${GREEN}✓${RESET} $APP_URL/healthz returns ok"
else warn "/healthz returned '$HEALTH'"; SKIPPED+=("/healthz check on $APP_URL"); fi
say "New address: ${BOLD}$APP_URL${RESET}"
pause

# ── 5 ────────────────────────────────────────────────────────────────────
stage "Google: allow sign-in on the new address"
open_url "https://console.cloud.google.com/auth/clients"
step "Open the OAuth client you made for Kereta (go-live.sh called it Kereta)."
step "Authorized redirect URIs → Add URI:"
note "    $APP_URL/auth/google/callback"
step "Keep the old kereta one for now. Save."
step "Optional: rename the client to Lejar (the name is only shown to you)."
note "Google can take a few minutes to accept a new redirect URI."
pause "Saved? Press Enter"

# ── 6 ────────────────────────────────────────────────────────────────────
stage "Sign in and check your data"
open_url "$APP_URL"
step "Sign in with Google on the new address."
step "Check your vehicles, their service history and a receipt photo are all there."
note "They live in the same database and bucket, so nothing should be missing."
if ! confirm "Signed in and everything is there?"; then
  warn "Stop here: don't delete the old worker. Kereta still works at ${OLD_URL:-its old address}."
  note "If sign-in says redirect_uri_mismatch, wait a few minutes after stage 5 and retry."
  note "Fix that, then re-run this wizard: it keeps the values already saved."; exit 1
fi
open_url "https://console.cloud.google.com/auth/branding"
step "Branding → App name: Lejar."
step "App home page: $APP_URL/   Privacy policy link: $APP_URL/privacy   → Save."
pause

# ── 7 ────────────────────────────────────────────────────────────────────
stage "iPhone: swap the Home Screen icon"
say "On your iPhone, in Safari, open: ${BOLD}$APP_URL${RESET}"
step "Sign in, then Share → Add to Home Screen. The dark LEJAR stamp icon should appear."
step "Open Lejar from the Home Screen once to check it starts full screen."
step "Long-press the old Kereta icon → Remove App → Delete from Home Screen."
confirm "Done on the iPhone?" || SKIPPED+=("swap the iPhone Home Screen icon")

# ── 8 ────────────────────────────────────────────────────────────────────
stage "Retire the old 'kereta' worker"
warn "This deletes the old worker and its address. Your data stays: it's in D1 'kereta' and R2 'kereta-receipts'."
if confirm "Delete the 'kereta' worker now?"; then
  if npx wrangler delete --name kereta; then say "${GREEN}✓${RESET} deleted the kereta worker"
  else SKIPPED+=("delete the kereta worker (npx wrangler delete --name kereta)"); fi
else
  SKIPPED+=("delete the kereta worker when you're ready (npx wrangler delete --name kereta)")
fi
open_url "https://console.cloud.google.com/auth/clients"
step "In the same OAuth client, remove the old redirect URI:"
note "    ${OLD_URL:-https://kereta.<subdomain>.workers.dev}/auth/google/callback"
confirm "Removed it?" || SKIPPED+=("remove the old kereta redirect URI in Google")

finish
say "Lejar is live at $APP_URL"
}

run_wizard "$@"; exit
